mapper.select:
select * from category


        and name like concat('%',#{name},'%')


        and type = #{type}


        and store_id = #{storeId}


order by sort asc , create_time desc

mapper.update:
update category


        type = #{type},


        name = #{name},


        sort = #{sort},


        status = #{status},


        update_time = #{updateTime},


        update_user = #{updateUser}


where id = #{id}

    and store_id = #{storeId}

mapper.select:
select * from category
where status = 1

    and type = #{type}


    and store_id = #{storeId}

order by sort asc,create_time desc
